import { useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";

type TeamRole = "owner" | "admin" | "member";

export interface TeamMember {
  id: string;
  user_id: string;
  role: TeamRole;
  joined_at: string;
  email?: string;
}

export interface TeamInvitation {
  id: string;
  email: string;
  role: TeamRole;
  status: string;
  created_at: string;
  expires_at: string;
}

export interface Team {
  id: string;
  name: string;
  owner_id: string;
}

export function useTeam() {
  const { user } = useAuth();
  const userId = user?.id;

  const { data, isLoading, refetch } = useQuery({
    queryKey: ["team", userId],
    queryFn: async () => {
      if (!userId) return { team: null, members: [], invitations: [], myRole: null };

      // Get user's owned team
      const { data: tmData } = await (supabase as any)
        .from("team_members")
        .select("team_id, role")
        .eq("user_id", userId)
        .eq("role", "owner")
        .limit(1)
        .maybeSingle();

      if (!tmData?.team_id) return { team: null, members: [], invitations: [], myRole: null };

      const teamId = tmData.team_id;

      // Fetch team, members, invitations in parallel
      const [teamRes, membersRes, invitationsRes] = await Promise.all([
        (supabase as any).from("teams").select("id, name, owner_id").eq("id", teamId).single(),
        (supabase as any).from("team_members").select("id, user_id, role, joined_at").eq("team_id", teamId).order("joined_at"),
        (supabase as any).from("team_invitations").select("id, email, role, status, created_at, expires_at").eq("team_id", teamId).eq("status", "pending").order("created_at", { ascending: false }),
      ]);

      const team: Team | null = teamRes.data ?? null;
      const rawMembers = (membersRes.data ?? []) as TeamMember[];
      const invitations = (invitationsRes.data ?? []) as TeamInvitation[];

      // Get emails for members from auth admin (via profiles or user metadata)
      // Since we can't query auth.users from client, we'll get emails from profiles
      // Actually profiles don't store email. User email is in auth.users which client can't query.
      // Workaround: use user's own email for self, show user_id for others until we add email to team_members
      const members = rawMembers.map((m) => ({
        ...m,
        email: m.user_id === userId ? user?.email ?? undefined : undefined,
      }));

      return { team, members, invitations, myRole: tmData.role as TeamRole };
    },
    enabled: !!userId,
    staleTime: 60_000,
  });

  return {
    team: data?.team ?? null,
    members: data?.members ?? [],
    invitations: data?.invitations ?? [],
    myRole: data?.myRole ?? null,
    isLoading,
    refetch,
  };
}
```

